import sys, json
import pandas as pd
import numpy as np

def to_py(v):
    if isinstance(v, (np.floating, np.integer)):
        return float(v)
    return float(v)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    def add(entity, metric, period, value, formula, kind="generic"):
        if value is None:
            return
        try:
            if pd.isna(value):
                return
        except TypeError:
            pass
        val = to_py(value)
        if kind == "money":
            val = round(val, 2)
        elif kind == "pct":
            val = round(val, 1)
        else:
            val = round(val, 2)
        facts.append({
            "entity": entity,
            "metric": metric,
            "period": period,
            "value": val,
            "formula": formula
        })

    # ---- Totals ----
    rev_tw_sum = df["Revenue_TW"].dropna().sum()
    rev_lw_sum = df["Revenue_LW"].dropna().sum()
    rev_ly_sum = df["Revenue_LY"].dropna().sum()
    units_tw_sum = df["Units_TW"].dropna().sum()
    units_lw_sum = df["Units_LW"].dropna().sum()
    orders_tw_sum = df["Orders_TW"].dropna().sum()
    orders_lw_sum = df["Orders_LW"].dropna().sum()

    add("TOTAL", "revenue", "TW", rev_tw_sum, "sum(Revenue_TW)", "money")
    add("TOTAL", "revenue", "LW", rev_lw_sum, "sum(Revenue_LW)", "money")
    if rev_ly_sum and not pd.isna(rev_ly_sum) and rev_ly_sum != 0:
        add("TOTAL", "revenue", "LY", rev_ly_sum, "sum(Revenue_LY)", "money")

    add("TOTAL", "units", "TW", units_tw_sum, "sum(Units_TW)", "count")
    add("TOTAL", "units", "LW", units_lw_sum, "sum(Units_LW)", "count")

    add("TOTAL", "orders", "TW", orders_tw_sum, "sum(Orders_TW)", "count")
    add("TOTAL", "orders", "LW", orders_lw_sum, "sum(Orders_LW)", "count")

    if rev_lw_sum and rev_lw_sum != 0:
        wow_total = (rev_tw_sum - rev_lw_sum) / rev_lw_sum * 100
        add("TOTAL", "revenue", "WoW", wow_total,
            "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100", "pct")

    if rev_ly_sum and not pd.isna(rev_ly_sum) and rev_ly_sum != 0:
        yoy_total = (rev_tw_sum - rev_ly_sum) / rev_ly_sum * 100
        add("TOTAL", "revenue", "YoY", yoy_total,
            "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100", "pct")

    # ---- Top entities by rank/revenue ----
    if "Rank" in df.columns:
        top_df = df.sort_values("Rank").head(3)
    else:
        top_df = df.sort_values("Revenue_TW", ascending=False).head(3)

    for _, row in top_df.iterrows():
        ent = row["Entity"]
        add(ent, "revenue", "TW", row.get("Revenue_TW"), "Revenue_TW", "money")
        if "Share_Pct" in df.columns:
            add(ent, "share", "TW", row.get("Share_Pct"),
                "Revenue_TW / sum(Revenue_TW) * 100 (given as Share_Pct)", "pct")
        if "Rank" in df.columns:
            add(ent, "rank", "TW", row.get("Rank"), "Rank by Revenue_TW", "count")

    # ---- Top WoW movers ----
    if "WoW_Pct" in df.columns:
        wow_sorted = df.dropna(subset=["WoW_Pct"]).sort_values("WoW_Pct", ascending=False)
        top_gain = wow_sorted.head(3)
        for _, row in top_gain.iterrows():
            add(row["Entity"], "revenue", "WoW", row["WoW_Pct"],
                "(Revenue_TW - Revenue_LW) / Revenue_LW * 100", "pct")

    # ---- Top YoY movers ----
    if "YoY_Pct" in df.columns:
        yoy_sorted = df.dropna(subset=["YoY_Pct"]).sort_values("YoY_Pct", ascending=False)
        top_yoy = yoy_sorted.head(3)
        for _, row in top_yoy.iterrows():
            add(row["Entity"], "revenue", "YoY", row["YoY_Pct"],
                "(Revenue_TW - Revenue_LY) / Revenue_LY * 100", "pct")

    # Trim to at most 25 facts
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
